    def map(self, second_heading=-1):
        a = [Point(-8, 0, 1, 0, 1), Point(0, 0, 1, 0, 2, True),
             Point(0, 5, 0, 1, 3)]
        b = [Point(8, 0, second_heading, 0, 4),
             Point(0, 1, second_heading, 0, 5, True),
             Point(-6, 1, -1, 0, 6)]
